// test/radioVisualizerMath.test.js
// Characterisation tests for the pure helpers extracted out of
// js/radioVisualizer.js into js/radioVisualizer/{palettes,settings}.js.
//
// Every expectation here was generated by evaluating the helper block as it
// stood on HEAD before the extraction, so a passing run means the move was
// behaviour-preserving — including the quirks (clamp with min > max, `|| 0.55`
// swallowing an explicit amplitude of 0, the un-spaced rgba() string on the
// invalid-colour path, and PALETTES.neon as the render fallback while
// DEFAULTS.palette is 'horizon').
//
// Run with: npm test
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { PALETTES } from '../js/radioVisualizer/palettes.js';
import {
    DEFAULTS,
    VISUALIZER_PREFS_KEY,
    readVisualizerPrefs,
    writeVisualizerPrefs,
    clamp,
    alpha,
    pickColor,
    setGlow,
    beatPulse,
    ampScale,
    shuffleNoRepeat,
    smoothstep,
    hexToRgb,
    rgbaTuple,
    lerpTuple,
    cssRgba
} from '../js/radioVisualizer/settings.js';
import {
    DAY_CYCLE_MS,
    UNDER_HORIZON_MS,
    skyPaletteFrames,
    blendedSkyStops,
    dayCycleState
} from '../js/radioVisualizer/sky.js';

const HORIZON = ['#00f0ff', '#ff2bd6', '#b8ff3c', '#7b5cff', '#ff9f1c'];

/** Run `fn` with Math.random driven by a fixed sequence, then restore it. */
function withRandom(sequence, fn) {
    const real = Math.random;
    let i = 0;
    Math.random = () => sequence[i++ % sequence.length];
    try {
        return fn();
    } finally {
        Math.random = real;
    }
}

/** Run `fn` with a Map-backed localStorage stub, then restore the global. */
function withStorage(fn) {
    const store = new Map();
    const had = Object.prototype.hasOwnProperty.call(globalThis, 'localStorage');
    const previous = globalThis.localStorage;
    globalThis.localStorage = {
        getItem: (key) => (store.has(key) ? store.get(key) : null),
        setItem: (key, value) => store.set(key, String(value))
    };
    try {
        return fn(store);
    } finally {
        if (had) globalThis.localStorage = previous;
        else delete globalThis.localStorage;
    }
}

describe('radio visualizer · palettes', () => {
    it('keeps every named ramp, in order, as five hex stops', () => {
        assert.deepEqual(Object.keys(PALETTES), [
            'neon', 'horizon', 'sunset', 'aurora', 'mono', 'ocean', 'vapor', 'dark-ocean', 'night-sky'
        ]);
        for (const [name, ramp] of Object.entries(PALETTES)) {
            assert.equal(ramp.length, 5, `${name} should have 5 stops`);
            for (const stop of ramp) assert.match(stop, /^#[0-9a-f]{6}$/, `${name} stop ${stop}`);
        }
        assert.deepEqual(PALETTES.horizon, HORIZON);
    });
});

describe('radio visualizer · settings defaults + prefs', () => {
    it('exposes the default settings shape', () => {
        assert.deepEqual(DEFAULTS, {
            mode: 'mountains',
            palette: 'horizon',
            sensitivity: 1,
            amplitude: 0.55,
            density: 1,
            speed: 1,
            travel: 0.55,
            glow: 0.85,
            background: 'dark',
            bpm: 120
        });
        assert.equal(VISUALIZER_PREFS_KEY, 'matrix_radio_visualizer_prefs');
    });

    it('round-trips prefs through the storage key', () => {
        withStorage((store) => {
            writeVisualizerPrefs({ mode: 'spaceTrip', bpm: 90 });
            assert.equal(store.get(VISUALIZER_PREFS_KEY), '{"mode":"spaceTrip","bpm":90}');
            assert.deepEqual(readVisualizerPrefs(), { mode: 'spaceTrip', bpm: 90 });
        });
    });

    it('degrades to {} when the stored blob is missing or corrupt', () => {
        withStorage((store) => {
            assert.deepEqual(readVisualizerPrefs(), {});
            store.set(VISUALIZER_PREFS_KEY, '{not json');
            assert.deepEqual(readVisualizerPrefs(), {});
            store.set(VISUALIZER_PREFS_KEY, 'null');
            assert.deepEqual(readVisualizerPrefs(), {});
        });
    });

    it('swallows storage write failures (quota / private mode)', () => {
        withStorage(() => {
            globalThis.localStorage.setItem = () => {
                throw new Error('quota');
            };
            assert.doesNotThrow(() => writeVisualizerPrefs({ mode: 'bars' }));
        });
    });
});

describe('radio visualizer · colour + timing math', () => {
    it('clamps into range and keeps the min > max quirk', () => {
        assert.equal(clamp(5, 0, 1), 1);
        assert.equal(clamp(-3, 0, 1), 0);
        assert.equal(clamp(0.4, 0, 1), 0.4);
        assert.equal(clamp(0.5, 1, 0), 0); // min wins over max
        assert.equal(clamp('0.5', 0, 1), 0.5);
        assert.equal(clamp(2, 0, 10), 2);
    });

    it('expands 3- and 6-char hex and falls back to white', () => {
        assert.equal(alpha('#fff', 0.5), 'rgba(255, 255, 255, 0.5)');
        assert.equal(alpha('#ffffff', 0.5), 'rgba(255, 255, 255, 0.5)');
        assert.equal(alpha('#abc', 0.5), 'rgba(170, 187, 204, 0.5)');
        assert.equal(alpha('#aabbcc', 0.5), 'rgba(170, 187, 204, 0.5)');
        assert.equal(alpha('#38bdf8', 0.5), 'rgba(56, 189, 248, 0.5)');
        assert.equal(alpha('#102030', 0), 'rgba(16, 32, 48, 0)');
        assert.equal(alpha('#102030', 1), 'rgba(16, 32, 48, 1)');
        // Invalid colours take a different (un-spaced) formatting path.
        assert.equal(alpha('nope', 0.5), 'rgba(255,255,255,0.5)');
        assert.equal(alpha('', 0.25), 'rgba(255,255,255,0.25)');
        assert.equal(alpha('#12345', 0.5), 'rgba(255,255,255,0.5)');
    });

    it('wraps palette indices and falls back to the first stop', () => {
        assert.deepEqual(
            [0, 1, 2, 3, 4, 5, -1, 7].map((i) => pickColor(HORIZON, i)),
            ['#00f0ff', '#ff2bd6', '#b8ff3c', '#7b5cff', '#ff9f1c', '#00f0ff', '#00f0ff', '#b8ff3c']
        );
    });

    it('drives canvas glow from the first palette stop', () => {
        const ctx = {};
        setGlow(ctx, HORIZON, 0.85);
        assert.equal(ctx.shadowBlur, 8 + 0.85 * 18);
        assert.equal(ctx.shadowColor, 'rgba(0, 240, 255, 0.7)');
        setGlow(ctx, HORIZON, 0);
        assert.equal(ctx.shadowBlur, 8 + 0.65 * 18); // falsy glow → 0.65
    });

    it('derives the beat envelope from tempo and wall clock', () => {
        assert.deepEqual(beatPulse(120, 0), { phase: 0, pulse: 1, tempo: 120 });
        assert.deepEqual(beatPulse(120, 60000), { phase: 0, pulse: 1, tempo: 120 });
        assert.deepEqual(
            beatPulse(120, 1234),
            { phase: 0.46799999999999997, pulse: 0.21988110838544025, tempo: 120 }
        );
        assert.equal(beatPulse(0, 30000).tempo, 120); // falsy → 120
        assert.equal(beatPulse(10, 30000).tempo, 10);
        assert.equal(beatPulse(200, 30000).tempo, 200);
        assert.equal(beatPulse(500, 30000).tempo, 200); // clamped high
        assert.equal(beatPulse('120', 30000).tempo, 120);
    });

    it('scales amplitude with a falsy-zero quirk', () => {
        assert.equal(ampScale({ amplitude: 0.55, sensitivity: 1 }), 0.55);
        assert.equal(ampScale({ amplitude: 1, sensitivity: 1 }), 1);
        assert.equal(ampScale({ amplitude: 0.5, sensitivity: 2 }), 0.5); // sensitivity unused
        assert.equal(ampScale({ amplitude: 0, sensitivity: 1 }), 0.55); // 0 is falsy → default
        assert.equal(ampScale({ amplitude: 9, sensitivity: 1 }), 1.5); // clamped high
        assert.equal(ampScale({ amplitude: -9, sensitivity: 1 }), 0.15);
    });

    it('smoothsteps with hard edges', () => {
        assert.equal(smoothstep(0, 1, 0), 0);
        assert.equal(smoothstep(0, 1, 0.5), 0.5);
        assert.equal(smoothstep(0, 1, 1), 1);
        assert.equal(smoothstep(0.2, 0.8, 0.5), 0.4999999999999998);
        assert.equal(smoothstep(0, 1, -1), 0);
        assert.equal(smoothstep(0, 1, 2), 1);
    });

    it('parses hex to rgb tuples, lerps, and formats css', () => {
        assert.deepEqual(hexToRgb('#fff'), [255, 255, 255]);
        assert.deepEqual(hexToRgb('#ffffff'), [255, 255, 255]);
        assert.deepEqual(hexToRgb('#38bdf8'), [56, 189, 248]);
        assert.deepEqual(hexToRgb('#000'), [0, 0, 0]);
        assert.deepEqual(hexToRgb('nope'), [255, 255, 255]);

        assert.deepEqual(rgbaTuple('#38bdf8', 0.5), [56, 189, 248, 0.5]);
        assert.deepEqual(rgbaTuple('#fff', 0.5), [255, 255, 255, 0.5]);

        assert.deepEqual(lerpTuple([0, 0, 0, 0], [100, 200, 50, 1], 0.5), [50, 100, 25, 0.5]);
        assert.deepEqual(lerpTuple([255, 255, 255, 1], [0, 0, 0, 0], 0), [255, 255, 255, 1]);

        assert.equal(cssRgba([10, 20, 30, 0.5]), 'rgba(10, 20, 30, 0.5)');
        assert.equal(cssRgba([255.4, 0.6, 0, 1]), 'rgba(255, 1, 0, 1)'); // rounds
    });

    it('shuffles without repeating the last scene', () => {
        assert.deepEqual(
            withRandom([0.42, 0.11, 0.87, 0.5], () => shuffleNoRepeat(['cactus', 'forest'], null)),
            ['forest', 'cactus']
        );
        assert.deepEqual(
            withRandom([0.42], () => shuffleNoRepeat(['cactus', 'forest'], 'cactus')),
            ['forest', 'cactus']
        );
        assert.deepEqual(
            withRandom([0.42, 0.11, 0.87], () => shuffleNoRepeat(['a', 'b', 'c', 'd'], 'a')),
            ['c', 'd', 'a', 'b']
        );
        // A single item can't avoid repeating, and an empty list stays empty.
        assert.deepEqual(shuffleNoRepeat(['only'], 'only'), ['only']);
        assert.deepEqual(shuffleNoRepeat([], null), []);
    });
});

describe('radio visualizer · sky + day cycle', () => {
    it('keeps the day-cycle constants', () => {
        assert.equal(DAY_CYCLE_MS, 65000);
        assert.equal(UNDER_HORIZON_MS, 5000);
    });

    it('builds five sky stops per period from the palette', () => {
        const frames = skyPaletteFrames(HORIZON);
        assert.deepEqual(Object.keys(frames), ['night', 'dawn', 'day', 'sunset', 'dusk']);
        assert.deepEqual(frames.night, [
            [1, 2, 8, 1], [7, 16, 31, 1], [123, 92, 255, 0.28], [0, 240, 255, 0.1], [0, 0, 0, 1]
        ]);
        assert.deepEqual(frames.day, [
            [42, 24, 112, 1], [123, 92, 255, 0.9], [0, 240, 255, 0.8], [255, 43, 214, 0.55], [10, 16, 40, 1]
        ]);
        // Missing 4th/5th stops fall back to palette[0] / palette[2].
        const short = skyPaletteFrames(['#00f0ff', '#ff2bd6', '#b8ff3c']);
        assert.deepEqual(short.night[2], [0, 240, 255, 0.28]);
        assert.deepEqual(short.night[3], [0, 240, 255, 0.1]);
    });

    it('blends keyframe to keyframe across the cycle', () => {
        const frames = skyPaletteFrames(HORIZON);
        assert.deepEqual(blendedSkyStops(HORIZON, 0), frames.night);
        assert.deepEqual(blendedSkyStops(HORIZON, 0.52), frames.sunset); // exact keyframe
        assert.deepEqual(blendedSkyStops(HORIZON, 1), frames.night);
        const mid = blendedSkyStops(HORIZON, 0.5);
        assert.equal(mid.length, 5);
        assert.deepEqual(mid[0], [100.24, 11.456000000000001, 63.61600000000001, 1]);
    });

    it('walks the sun then moon through the day cycle', () => {
        const dawn = dayCycleState(6500, 0);
        assert.equal(dawn.period, 'dawn');
        assert.equal(dawn.elapsed, 6500);
        assert.equal(dawn.sunArc, 0.19230769230769232);
        assert.equal(dawn.dayness, 0.6183554069783999);

        const sunset = dayCycleState(33800, 0);
        assert.equal(sunset.period, 'sunset');
        assert.equal(sunset.sunsetness, 1);
        assert.equal(dayCycleState(39000, 0).duskness, 0.8333333333333331);

        const night = dayCycleState(48750, 0);
        assert.equal(night.period, 'night');
        assert.equal(night.moonness, 0.9960585221847017);
        assert.equal(dayCycleState(61750, 0).moonArc, 1);

        assert.deepEqual(
            [0, 0.1, 0.3, 0.52, 0.6, 0.75, 0.95].map((t) => dayCycleState(t * 65000, 0).period),
            ['dawn', 'dawn', 'day', 'sunset', 'dusk', 'night', 'night']
        );
    });

    it('wraps negative or offset cycle starts', () => {
        assert.equal(dayCycleState(-65000, 0).elapsed, 0);
        assert.equal(dayCycleState(0, 1000).elapsed, 64000);
        assert.equal(dayCycleState(1000, 0).elapsed, 1000);
        assert.equal(dayCycleState(0, 1000).period, 'night');
    });
});
